import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {sourceScope} from './build.mjs';
import {executionGuard,byteDiff} from './driver.mjs';
const here=path.dirname(fileURLToPath(import.meta.url));
const manifest=JSON.parse(fs.readFileSync(path.join(here,'manifest.json'),'utf8'));
test('UNBOUND proof cannot reach browser launch',()=>assert.throws(()=>executionGuard({...manifest,executionBound:false},{}),/UNBOUND/));
test('One altered saved channel is not a tolerant pixel pass',()=>{const a=Buffer.from([1,2,3,255,4,5,6,255]),b=Buffer.from(a);b[5]^=1;assert.deepEqual(byteDiff(a,b),{changedBytes:1,changedPixels:1,maxDifference:1});});
test('Raw size mismatch is rejected',()=>assert.throws(()=>byteDiff(Buffer.alloc(4),Buffer.alloc(8)),/size/));
test('Original scope guard rejects unowned same-value target resizing',()=>{const safe='if(now-lastUI>300){lastUI=now; if(navigation.hidden||minimap.hidden)return;';assert.equal(sourceScope(safe).noTargetBackingSizeWriter,true);assert.throws(()=>sourceScope(safe+'minimap.width = minimap.width;'),/backing-size/);assert.throws(()=>sourceScope(safe+'minimap.setAttribute("height","290");'),/attribute/);});
test('Fixed readback schedule reserves four untouched composition pairs',()=>{const s=JSON.parse(fs.readFileSync(path.join(here,'schedule.json'),'utf8'));assert.equal(s.checkpoints.length,26);assert.equal(s.groups.length,8);const c=s.checkpoints.filter(v=>v.composition);assert.equal(c.length,4);assert.equal(new Set(c.map(v=>v.pair)).size,4);assert.ok(c.every(v=>v.readbacksPerCanvasBefore===0));});

import {DeadlineBudget,EvidenceBudget,IssueLedger,classifyRequest,validateBrowserVersion,closeOwnedBrowser} from './driver.mjs';
test('Expired setup refuses invocation and cannot pass timeout zero to Playwright',async()=>{let now=10,calls=0;const b=new DeadlineBudget({absoluteMs:20,workMs:10},0,()=>now);await assert.rejects(b.call('launch',ms=>{calls++;assert.ok(ms>0);}),/deadline/);assert.equal(calls,0);});
test('Resolution after monotonic deadline cannot become success',async()=>{let now=0;const b=new DeadlineBudget({absoluteMs:20,workMs:10},0,()=>now);await assert.rejects(b.call('setup',ms=>{assert.equal(ms,10);now=11;return 'late';}),/completed after deadline/);});
test('Stalled protocol setup is bounded independently of a watchdog',async()=>{const b=new DeadlineBudget({absoluteMs:1000,workMs:500});await assert.rejects(b.call('never resolves',()=>new Promise(()=>{}),{limit:5}),/deadline/);});
test('Cleanup uses the remaining absolute budget instead of renewing ten seconds',async()=>{let now=175000;const b=new DeadlineBudget({absoluteMs:180000,workMs:170000},0,()=>now);let allowance;await b.call('cleanup',ms=>{allowance=ms;now=179999;},{until:Math.min(b.absolute,now+10000)});assert.equal(allowance,5000);now=180000;await assert.rejects(b.call('late close',()=>{throw new Error('must not start');},{until:b.absolute}),/deadline reached before start/);});
const smallBounds={outputBytes:2000,ancillaryBytes:1000,pngBytes:400,reservedStatusBytes:200,reservedFailureBytes:100,reservedAuditBytes:200};
test('Evidence cannot consume reserved status failure and audit capacity',()=>{const b=new EvidenceBudget(smallBounds);b.admit(500,'metadata');assert.throws(()=>b.admit(1,'metadata'),/reserved reports/);b.terminal('capture-status.json',200);b.terminal('terminal-error.json',100);b.terminal('audit.json',200);assert.equal(b.receipt().regularAncillaryBytes+b.reserve,1000);});
test('Raw output also preserves all report slots and rejects oversized terminal fallback',()=>{const b=new EvidenceBudget(smallBounds);b.admit(1500,'raw');assert.throws(()=>b.admit(1,'raw'),/reserved reports/);assert.throws(()=>b.terminal('terminal-error.json',101),/slot/);assert.throws(()=>b.terminal('unknown.json',1),/slot/);});
test('Repeated errors and network failures retain bounded receipts and sticky overflow',()=>{const l=new IssueLedger();for(let i=0;i<1000;i++)l.networkFailure('bad','https://example.invalid/'+String(i),'x'.repeat(4000));assert.equal(l.state.observed,1000);assert.equal(l.network.observed,1000);assert.ok(l.errors.length<=64&&l.state.storedBytes<=65536&&l.state.overflow);assert.ok(l.network.rows.length<=128&&l.network.storedBytes<=131072&&l.network.overflow);});
test('Only fixed local fixture requests and explicitly benign favicon are allowed',()=>{const origin='http://127.0.0.1:1234',pairs=['p1','p2'];assert.equal(classifyRequest(origin+'/fixture.js',origin,'GET',pairs,'script'),'script');assert.equal(classifyRequest(origin+'/fixture.html?side=candidate&pair=p2',origin,'GET',pairs,'document'),'html');assert.equal(classifyRequest(origin+'/favicon.ico',origin,'GET',pairs,'other'),'favicon');for(const [url,method]of [[origin+'/unknown','GET'],[origin+'/fixture.js?other=1','GET'],[origin+'/fixture.html?side=control&pair=p2','GET'],[origin+'/fixture.js','POST'],['https://example.invalid/fixture.js','GET']])assert.equal(classifyRequest(url,origin,method,pairs),null);});
test('Exact products and asymmetric recorded revision policy remain explicit',()=>{const p=manifest.runtime.browserLanes,metal={product:p.metal.product,revision:'@'+p.metal.revision},software={product:p.swiftshader.product,revision:'@'+'a'.repeat(40)};assert.equal(validateBrowserVersion(metal,'metal',p).previouslyVerified,true);assert.equal(validateBrowserVersion(software,'swiftshader',p).previouslyVerified,false);assert.throws(()=>validateBrowserVersion({...software,product:p.metal.product},'swiftshader',p),/product/);assert.throws(()=>validateBrowserVersion({...software,revision:'unknown'},'swiftshader',p),/revision/);assert.throws(()=>validateBrowserVersion({...metal,revision:'@'+'a'.repeat(40)},'metal',p),/retained revision/);});

test('Expired graceful-close budget still issues one owned force-stop and cannot acknowledge success',async()=>{let now=2000,kills=0,closes=0;const time=new DeadlineBudget({absoluteMs:2000,workMs:1000},0,()=>now),failures=[];const server={close(){closes++;return Promise.resolve();},kill(){kills++;return Promise.resolve();},process(){return {exitCode:null,signalCode:'SIGKILL'};}};const result=await closeOwnedBrowser(server,time,2000,e=>failures.push(e.message));assert.equal(closes,0);assert.equal(kills,1);assert.equal(result.acknowledged,false);assert.equal(result.forcedKillIssued,true);assert.ok(failures.length>=1);});
